const {
  isSharedComponentsKey,
  mergeSharedUnderMfeNamespace,
  normalizeFlatKey,
} = require('./mergeSharedUnderMfeNamespace');

const APPLANGA_TAG = 'main';

function resolveEntryValue(entry, useDraftValues) {
  if (entry && typeof entry === 'object' && useDraftValues && 'd' in entry) {
    return entry.d;
  }

  if (entry && typeof entry === 'object' && 'v' in entry) {
    return entry.v;
  }

  if (typeof entry === 'string') {
    return entry;
  }

  return entry || '';
}

function assignEntry(target, key, value) {
  target[key] = value;
}

function extractEntries(langData, useDraftValues) {
  if (!langData || typeof langData !== 'object') {
    console.warn('⚠️  No language data found in API response');
    return {};
  }

  const mfeEntries = {};
  const sharedEntries = {};
  let foundBranch = false;

  Object.values(langData).forEach((branch) => {
    if (!branch || typeof branch !== 'object' || !branch.entries) {
      return;
    }

    foundBranch = true;

    Object.keys(branch.entries).forEach((originalKey) => {
      const value = resolveEntryValue(branch.entries[originalKey], useDraftValues);

      if (isSharedComponentsKey(originalKey)) {
        assignEntry(sharedEntries, normalizeFlatKey(originalKey), value);
      } else {
        assignEntry(mfeEntries, originalKey, value);
      }
    });
  });

  if (!foundBranch) {
    console.warn(`⚠️  No entries found in language data (expected branches like "${APPLANGA_TAG}")`);
    return {};
  }

  return mergeSharedUnderMfeNamespace(mfeEntries, sharedEntries);
}

module.exports = { extractEntries, APPLANGA_TAG, resolveEntryValue };
